import math
import sys
n = int(sys.stdin.readline())

def f(l, r):
	if l == r:
		return l
	t = int(math.log2(r))
	if 2 ** t <= l:
		return f(l - 2 ** t, r - 2 ** t) + 2 ** t
	elif 2 ** (t + 1) - 1 <= r:
		return 2 ** (t + 1) - 1
	else:
		return 2 ** t - 1
for _ in range(n):
	(l, r) = tuple(map(int, sys.stdin.readline().split()))
	print(f(l, r))
